import {
  assertBindingTargetIdentFree,
  BINDING_TARGET_STAMP_HELPER,
  NAPI_BINDING_TARGET_EXPORT,
  NAPI_BINDING_TARGET_STAMP_FN,
} from './binding-target.js'

const bindingHeader = `/* eslint-disable */
// @ts-nocheck
/* auto-generated by NAPI-RS */
`

/**
 * Generate a deterministic CommonJS loader for one known `.node` artifact.
 *
 * Unlike the `node` loader in `js-binding.ts`, this performs no runtime
 * platform detection: no `process.platform`/`process.arch` checks, no
 * musl/glibc probing, no `child_process` usage, and no npm native package
 * fallback. The artifact is selected at build time.
 */
export function createDirectCjsBinding(
  artifactSpecifier: string,
  idents: string[],
  bindingTarget = 'native',
): string {
  assertBindingTargetIdentFree(idents)
  return `${bindingHeader}
const nativeBinding = require('${artifactSpecifier}')

${BINDING_TARGET_STAMP_HELPER}
// Keep the marker a statically visible CommonJS export for cjs-module-lexer
// (Node's CJS -> ESM named export detection), mirroring the node loader:
// the assignment target is this loader's own module.exports, and the alias
// below replaces it with the binding itself.
module.exports.${NAPI_BINDING_TARGET_EXPORT} = ${NAPI_BINDING_TARGET_STAMP_FN}(nativeBinding, '${bindingTarget}')
module.exports = nativeBinding
${idents
  .map((ident) => `module.exports.${ident} = nativeBinding.${ident}`)
  .join('\n')}
`
}

/**
 * Generate a deterministic ESM loader for one known `.node` artifact.
 *
 * Export semantics mirror `createEsmBinding`: named exports when `idents` is
 * non-empty, otherwise a default export. Only artifact resolution differs.
 */
export function createDirectEsmBinding(
  artifactSpecifier: string,
  idents: string[],
  bindingTarget = 'native',
): string {
  assertBindingTargetIdentFree(idents)
  const bindingTargetExport = `export const ${NAPI_BINDING_TARGET_EXPORT} = '${bindingTarget}'`
  const exportsCode =
    idents.length > 0
      ? `const { ${idents.join(', ')} } = nativeBinding
${idents.map((ident) => `export { ${ident} }`).join('\n')}
${bindingTargetExport}`
      : `export default nativeBinding
${bindingTargetExport}`
  return `${bindingHeader}
import { createRequire } from 'module'
const require = createRequire(import.meta.url)

const nativeBinding = require('${artifactSpecifier}')

${exportsCode}
`
}
